  "Victoire 2 points, défaite 1. Départage : confrontations directes, différence de points, points marqués. Phase finale : les 2 premiers de chaque groupe et les 2 meilleurs troisièmes ; les autres jouent le tournoi de consolation.": "Zwycięstwo 2 punkty, porażka 1. Przy równej liczbie punktów: mecze bezpośrednie, różnica punktów, zdobyte punkty. Turniej finałowy: 2 najlepsze drużyny z każdej grupy i 2 najlepsze z trzecich miejsc; pozostałe grają w turnieju pocieszenia.",
  "Victoire 2 points, défaite 1. Départage : confrontations directes, différence de points, points marqués. Toutes les sélections du continent vont en phase finale ; le classement donne les têtes de série.": "Zwycięstwo 2 punkty, porażka 1. Przy równej liczbie punktów: mecze bezpośrednie, różnica punktów, zdobyte punkty. Wszystkie reprezentacje kontynentu grają w turnieju finałowym; tabela decyduje o rozstawieniu.",
  "Victoire 2 points, défaite 1. Départage : confrontations directes, différence de points, points marqués. Le classement fixe les têtes de série de la Coupe du monde et du tournoi de consolation.": "Zwycięstwo 2 punkty, porażka 1. Przy równej liczbie punktów: mecze bezpośrednie, różnica punktów, zdobyte punkty. Tabela ustala rozstawienie na mistrzostwach świata i w turnieju pocieszenia.",
  "Victoire 2 points, défaite 1. Départage : confrontations directes, différence de points, points marqués.": "Zwycięstwo 2 punkty, porażka 1. Przy równej liczbie punktów: mecze bezpośrednie, różnica punktów, zdobyte punkty.",
