  ": parquet aux couleurs du club dans le direct quand vous recevez et salle personnalisée (couleurs, façade, toit, ambiance) dans l'onglet Personnalisation, sous le Guide, avec le logo, les maillots, le trigramme et le nom de la salle ; apparence des jeunes de l'académie (bouton « Personnaliser l'apparence » sur leur carte) et des joueurs qu'elle a formés, et numéro de maillot de chaque joueur (carte « Personnalisation » de leur fiche). Tous les joueurs ont un numéro, visible sur leur fiche ; les numéros retirés au Hall of Fame ne sont plus portés.": ": parkiet w barwach klubu w transmisji na żywo, gdy grasz u siebie, i spersonalizowana hala (kolory, fasada, dach, klimat) w zakładce Personalizacja, pod Przewodnikiem, razem z logo, strojami, skrótem i nazwą hali; wygląd młodzików z akademii (przycisk „Dostosuj wygląd” na ich karcie) i wychowanych przez nią zawodników oraz numer na koszulce każdego zawodnika (karta „Personalizacja” na jego profilu). Każdy zawodnik ma numer, widoczny na jego profilu; numery zastrzeżone w Hall of Fame nie są już noszone.",
