  "Indisponible pour l'instant.": "Na razie niedostępne.",
  "Aucun manager classé pour l'instant : il faut un premier match officiel entre deux managers.": "Na razie brak sklasyfikowanych menedżerów: potrzebny jest pierwszy oficjalny mecz między dwoma menedżerami.",
  "Votre note :": "Twoja ocena:",
  ". Vous serez classé après votre premier match officiel contre un autre manager.": ". Zostaniesz sklasyfikowany po swoim pierwszym oficjalnym meczu z innym menedżerem.",
  "{0} · {1} match": "{0} · {1} mecz",
  "{0} · {1} matchs": "{0} · mecze: {1}",
  "Note de départ 1500, qui monte ou descend à chaque match officiel contre un autre manager (plus l'adversaire est bien noté, plus la victoire rapporte). Les matchs contre l'IA et les amicaux ne comptent pas. {0} manager classé.": "Ocena startowa 1500, która rośnie lub spada po każdym oficjalnym meczu z innym menedżerem (im wyżej oceniony rywal, tym więcej daje zwycięstwo). Mecze z AI i towarzyskie się nie liczą. Sklasyfikowani menedżerowie: {0}.",
  "Note de départ 1500, qui monte ou descend à chaque match officiel contre un autre manager (plus l'adversaire est bien noté, plus la victoire rapporte). Les matchs contre l'IA et les amicaux ne comptent pas. {0} managers classés.": "Ocena startowa 1500, która rośnie lub spada po każdym oficjalnym meczu z innym menedżerem (im wyżej oceniony rywal, tym więcej daje zwycięstwo). Mecze z AI i towarzyskie się nie liczą. Sklasyfikowani menedżerowie: {0}.",
  "Le classement se départage par victoires puis par différence de points. Places 1 à 4 : play-offs. Barrage et relégation seulement s'il existe un championnat juste en dessous (couleurs et légende l'indiquent). Ce panneau résume votre position et l'écart avec les places clés.": "O kolejności w tabeli decydują zwycięstwa, a potem różnica punktów. Miejsca 1–4: play-offy. Baraże i spadek obowiązują tylko wtedy, gdy istnieje liga tuż niżej (wskazują to kolory i legenda). Ten panel podsumowuje twoją pozycję i dystans do kluczowych miejsc.",
  " ; s'il existe un championnat ouvert juste en dessous, le 10e est ": " ; jeśli tuż niżej jest otwarta liga, 10. drużyna ",
  "relégué": "spada",
  ", puis le 9e, et avec trois championnats en dessous le 7e et le 8e jouent un ": ", potem 9., a przy trzech ligach niżej 7. i 8. grają ",
  ". Seules les zones réellement en jeu sont colorées. Chaque équipe affiche sa forme récente. Un panneau \"course aux play-offs\" résume votre position, votre bilan et l'écart avec les places clés.": ". Kolorowe są tylko strefy, o które faktycznie toczy się gra. Każda drużyna pokazuje swoją ostatnią formę. Panel „wyścig o play-offy” podsumowuje twoją pozycję, twój bilans i dystans do kluczowych miejsc.",
  "Play-offs · le champion monte": "Play-offy · mistrz awansuje",
  "Play-offs · le champion monte en {0}": "Play-offy · mistrz awansuje do {0}",
  "Relégation directe (10e)": "Bezpośredni spadek (10. miejsce)",
  "Avance sur la {0}e (barrage)": "Przewaga nad {0}. miejscem (baraż)",
  "Avance sur la {0}e (relégation)": "Przewaga nad {0}. miejscem (spadek)",
  "Retard sur la {0}e (barrage)": "Strata do {0}. miejsca (baraż)",
  "Retard sur la {0}e (maintien)": "Strata do {0}. miejsca (utrzymanie)",
  "-0 pour": "-0 dla",
  "— {0}% des points": "— {0}% punktów",
  "— non pourvu —": "— nieobsadzone —",
  "— prochaine disponible le {0}": "— następna dostępna {0}",
  ", 5 et 6 maintien direct, 7 et 8": ", 5. i 6. bezpośrednie utrzymanie, 7. i 8.",
  ", agrandissable palier par palier depuis cet onglet, accélère cette progression. À ses 18 ans, une décision est requise pour chaque jeune : le promouvoir dans l'effectif pro (il dévoile alors son vrai palier de potentiel) ou le libérer définitivement. Sans décision avant la saison suivante, il est automatiquement libéré. L'historique des jeunes promus reste visible en bas de la page.": ", rozbudowywana poziom po poziomie z tej zakładki, przyspiesza ten rozwój. W wieku 18 lat trzeba podjąć decyzję w sprawie każdego młodzika: awansować go do pierwszego składu (wtedy ujawnia swój prawdziwy poziom potencjału) albo ostatecznie go zwolnić. Bez decyzji przed następnym sezonem zostaje zwolniony automatycznie. Historia awansowanych młodzików pozostaje widoczna na dole strony.",
  ", au moment où commence l'émission d'avant-match.": ", w chwili gdy zaczyna się studio przedmeczowe.",
  "d'abord (liseré orange et petit « 5 »), puis la rotation, puis la réserve (nom estompé), d'après la feuille de match actuelle ; cliquez un titre de colonne pour trier toute la liste. Pour chacun : poste, potentiel, âge, taille, salaire, forme, motivation et évaluation des derniers matchs. Le menu": "najpierw (pomarańczowa krawędź i małe „5”), potem rotacja, a następnie rezerwa (wyszarzone nazwisko), według aktualnego składu meczowego; kliknij nagłówek kolumny, aby posortować całą listę. Dla każdego: pozycja, potencjał, wiek, wzrost, pensja, forma, motywacja i ocena z ostatnich meczów. Menu",
  ", de plus en plus vite si vous la gardez plusieurs matchs de suite : +6, +8, +10, puis +12 par match. L'entraînement collectif": ", coraz szybciej, jeśli utrzymujesz ją przez kilka meczów z rzędu: +6, +8, +10, potem +12 na mecz. Trening zespołowy",
  ", du plus modeste au plus rare :": ", od najskromniejszego do najrzadszego:",
  ", gérer l'": ", zarządzać ",
  ", le {0}": ", {0}",
  ", mais doucement : rien les 2 premiers matchs d'absence, puis -2, -4 et au maximum -6 par match. Revenir à une tactique délaissée la fait remonter progressivement, jamais d'un coup.": ", ale łagodnie: nic przez pierwsze 2 mecze nieobecności, potem -2, -4 i maksymalnie -6 na mecz. Powrót do zaniedbanej taktyki stopniowo ją odbudowuje, nigdy od razu.",
  ", mais ils le prennent moins que d'autres zones.": ", ale łapią go wolniej niż inne strefy.",
  ", Mécontents": ", Niezadowoleni",
  ", plus floue, alignée sur les mêmes paliers :": ", mniej dokładna, oparta na tych samych poziomach:",
  ", régler l'": ", ustawić ",
  ", sponsor {0}": ", sponsor {0}",
