  ". Chaque équipe affiche sa forme récente. Un panneau \"course aux play-offs\" résume votre position, votre bilan et l'écart avec les places clés.": ". Każda drużyna pokazuje swoją ostatnią formę. Panel „wyścig o play-offy” podsumowuje twoją pozycję, twój bilans i dystans do kluczowych miejsc.",
  ". Chaque jour d'entraînement sur cet aspect ajoute {0} de connaissance tactique, crédités au prochain match où il est effectivement joué (voir Connaissance tactique).": ". Każdy dzień treningu tego aspektu dodaje {0} znajomości taktyki, zaliczanej w najbliższym meczu, w którym zostanie faktycznie zastosowany (patrz Znajomość taktyki).",
