  "'adminTeamName' doit correspondre à l'un des noms de 'teamNames'.": "'adminTeamName' musi odpowiadać jednej z nazw w 'teamNames'.",
  "'adminTeamName' doit être une chaîne non vide si fourni.": "'adminTeamName' musi być niepustym ciągiem, jeśli zostanie podane.",
  "'amount' (nombre non nul, positif ou négatif) requis.": "Wymagane 'amount' (liczba niezerowa, dodatnia lub ujemna).",
