  "\"Ça fait des semaines que je suis sur le banc sans la moindre explication, je demande à partir\", lâche {player}.": "„Od tygodni siedzę na ławce bez żadnego wyjaśnienia, proszę o odejście” – rzuca {player}.",
  "\"J'ai besoin de retrouver du temps de jeu ailleurs\", déclare {player}, visiblement lassé de la situation.": "„Muszę znaleźć minuty gdzie indziej” – oświadcza {player}, wyraźnie zmęczony sytuacją.",
  "\"Je ne me sens plus utile ici, il est temps d'envisager un nouveau projet\", confie {player} à la presse.": "„Nie czuję się tu już potrzebny, czas pomyśleć o nowym projekcie” – zwierza się {player} prasie.",
  "\"Le club connaît ma position, je souhaite être transféré au plus vite\", affirme {player}.": "„Klub zna moje stanowisko, chcę zostać sprzedany jak najszybciej” – stwierdza {player}.",
  "« À mi-parcours, cette victoire contre Adversaire test confirme qu'on est sur la bonne trajectoire, il reste encore la moitié de la saison pour la confirmer. On va continuer à travailler dans la continuité, avec quelques ajustements tactiques pour la seconde moitié. »": "„Na półmetku to zwycięstwo z Rywalem testowym potwierdza, że jesteśmy na dobrej drodze, ale została jeszcze połowa sezonu, żeby to udowodnić. Będziemy dalej pracować w ten sam sposób, z kilkoma korektami taktycznymi na drugą połowę.”",
  "« Comme l'appareil » suit le mode clair ou sombre de ton ordinateur ou de ton téléphone.": "„Jak w urządzeniu” podąża za trybem jasnym lub ciemnym twojego komputera lub telefonu.",
  "({0}-{1}, en cours)": "({0}-{1}, w trakcie)",
  "({1} pts) et": "({1} pkt) i",
  "({1}) · {2} d'efficacité sur {3}": "({1}) · {2} skuteczności na {3}",
  "({3} pts).": "({3} pkt).",
  "(aux deux niveaux) : Standard garde le comportement habituel. Adaptatif ajoute un vrai garbage time dès 10 points d'écart à partir du 3e quart-temps (au 4e quart-temps, à 18 points d'écart, les titulaires sortent pour ménager leur forme), et accélère légèrement le rythme dans les 5 dernières minutes d'un match serré.": "(na obu poziomach): Standardowe zachowuje zwykłe działanie. Adaptacyjne dodaje prawdziwy garbage time od 10 punktów różnicy począwszy od 3. kwarty (w 4. kwarcie przy 18 punktach różnicy starterzy schodzą, żeby oszczędzać formę) i lekko przyspiesza tempo w ostatnich 5 minutach wyrównanego meczu.",
  "(avec une petite jauge à 10 crans dans l'Effectif ; survolez le nom du palier pour voir son rang de 1 à 10). Un jeune joueur encore faible mais à fort potentiel peut, bien entraîné, dépasser largement un joueur déjà bon dont le potentiel est presque atteint.": "(z małym 10-stopniowym wskaźnikiem w Składzie; najedź na nazwę poziomu, aby zobaczyć jego pozycję od 1 do 10). Młody zawodnik, jeszcze słaby, ale z dużym potencjałem, może przy dobrym treningu wyraźnie prześcignąć zawodnika już dobrego, którego potencjał jest prawie wyczerpany.",
  "(c'est vous !)": "(to ty!)",
  "(cinq moments clés de la saison : début, mi-saison, fin de saison régulière, demi-finale puis finale des play-offs). Chaque interview pose deux questions, avec un ton à choisir pour chacune : Agressif amplifie le résultat (meilleur gain en cas de victoire, pire perte en cas de défaite), Mesuré reste sûr et modéré, Humble plafonne le gain en cas de victoire mais est le seul ton qui tourne une défaite en effet positif. Toute l'équipe est concernée. Ignorer l'interview (possible pendant 3 jours) n'a aucun effet. Un remplaçant qui ne joue quasiment jamais perd un peu de motivation chaque semaine, davantage s'il est meilleur que le titulaire de son poste.": "(pięć kluczowych momentów sezonu: początek, połowa sezonu, koniec sezonu zasadniczego, półfinał i finał play-offów). Każdy wywiad zawiera dwa pytania, a do każdego wybierasz ton: Agresywny wzmacnia efekt (większy zysk po zwycięstwie, większa strata po porażce), Wyważony jest bezpieczny i umiarkowany, Pokorny ogranicza zysk po zwycięstwie, ale jako jedyny zamienia porażkę w pozytywny efekt. Dotyczy to całej drużyny. Zignorowanie wywiadu (możliwe przez 3 dni) nie ma żadnego efektu. Rezerwowy, który prawie nigdy nie gra, co tydzień traci trochę motywacji, a więcej, jeśli jest lepszy od startera na swojej pozycji.",
  "(display-mode: standalone)": "(display-mode: standalone)",
  "(Division {0})": "(Dywizja {0})",
  "(en cours)": "(w trakcie)",
  "(en direct)": "(na żywo)",
  "(face à n'importe quel autre joueur ; pour un adversaire, seules ses caractéristiques révélées sont comparées) et": "(z dowolnym innym zawodnikiem; w przypadku rywala porównywane są tylko jego odkryte cechy) i",
  "(interrupteur manuel temporaire, en attendant un vrai système de paiement)": "(tymczasowy ręczny przełącznik, zanim pojawi się prawdziwy system płatności)",
  "(marché, jeunes, staff) et les finances du club.": "(rynek, młodzież, sztab) i finanse klubu.",
