  "29 caractéristiques (0 à 99) : Tir à mi-distance, Tir à 3 points, Jeu intérieur, Passe, Rebond, Contre, Dribble, Agilité, Défense extérieure, Défense intérieure, Mental, Endurance, Lancer franc, Pénétration, Création de tir, Interceptions, Puissance, Concentration, Anticipation, Leadership, Vitesse, Accélération, Force, Détente, Décision, Sang-froid, Détermination, Discipline et Vision. Sur chacune, plus le chiffre est élevé, mieux c'est, sans exception. La couleur donne le niveau en un coup d'œil : rouge en dessous de 45, grise de 45 à 64, verte de 65 à 79, dorée à partir de 80 (niveau élite).": "29 cech (od 0 do 99): Rzut z półdystansu, Rzut za 3 punkty, Gra pod koszem, Podanie, Zbiórka, Blok, Kozłowanie, Zwinność, Obrona na obwodzie, Obrona pod koszem, Psychika, Wytrzymałość, Rzut wolny, Penetracja, Kreowanie rzutu, Przechwyty, Moc, Koncentracja, Antycypacja, Przywództwo, Szybkość, Przyspieszenie, Siła, Wyskok, Podejmowanie decyzji, Opanowanie, Determinacja, Dyscyplina i Wizja gry. W każdej z nich im wyższa liczba, tym lepiej, bez wyjątku. Kolor pokazuje poziom na pierwszy rzut oka: czerwony poniżej 45, szary od 45 do 64, zielony od 65 do 79, złoty od 80 (poziom elitarny).",
  "2PTS": "2PKT",
