  "5 paliers, du plus frais (90-100) au plus épuisé (0-39, risque de blessure nettement accru). Baisse après chaque match selon le temps de jeu, remonte de 10 points par jour sans match (15 avec l'entraînement collectif Récupération).": "5 poziomów, od najświeższego (90-100) do najbardziej wyczerpanego (0-39, wyraźnie większe ryzyko kontuzji). Spada po każdym meczu zależnie od czasu gry, odbudowuje się o 10 punktów dziennie bez meczu (15 z treningiem zespołowym Regeneracja).",
