  "Achetez des joueurs aux enchères ou mettez les vôtres en vente. Chaque enchère dure 1 jour réel, et les autres clubs peuvent surenchérir jusqu'au bout. Filtres par poste, âge, potentiel, prix et caractéristiques, suivi de vos enchères en haut de page.": "Kupuj zawodników na licytacjach lub wystawiaj swoich na sprzedaż. Każda licytacja trwa 1 dzień rzeczywisty, a inne kluby mogą przebijać do samego końca. Filtry według pozycji, wieku, potencjału, ceny i cech, a twoje licytacje śledzisz na górze strony.",
