  "Agrandissement du Centre de formation refusé.": "Rozbudowa Ośrodka szkoleniowego odrzucona.",
  "Agrandissez votre salle place par place pour accueillir plus de spectateurs (brique Agrandir la salle : chaque catégorie de places a son prix par place et son nombre maximum de places), et réglez le prix du billet CATÉGORIE PAR CATÉGORIE : Tribune Supérieure, Tribune Centrale, Courtside et Loges VIP n'ont ni la même capacité, ni la même tolérance au prix. Seuls les matchs à domicile rapportent une recette. L'humeur des supporters influence le remplissage et la tolérance au prix. D'autres infrastructures sont proposées, chacune sur 5 niveaux comme le centre de formation : Boutique des supporters (revenu fixe chaque semaine), Station TV (revenu fixe chaque semaine), Salle de musculation (réduit le risque de blessure) et Espace bien-être (réduit la fatigue en match).": "Rozbudowuj halę miejsce po miejscu, aby pomieścić więcej widzów (blok Rozbuduj halę: każda kategoria miejsc ma swoją cenę za miejsce i maksymalną liczbę miejsc), i ustalaj ceny biletów KATEGORIA PO KATEGORII: Trybuna Górna, Trybuna Centralna, Courtside i Loże VIP mają różną pojemność i różną tolerancję na cenę. Przychód przynoszą tylko mecze u siebie. Nastrój kibiców wpływa na zapełnienie hali i tolerancję na cenę. Dostępne są też inne obiekty, każdy w 5 poziomach jak centrum szkolenia: Sklep kibica (stały przychód co tydzień), Stacja TV (stały przychód co tydzień), Siłownia (zmniejsza ryzyko kontuzji) i Strefa odnowy (zmniejsza zmęczenie w meczu).",
