  "Avant chaque match, réglez trois choses pour votre équipe dans la page Ordres (bouton « Donnez vos ordres » en haut, ou le bouton du match dans le Calendrier). Tout s'enregistre automatiquement à chaque changement, et le bouton \"Enregistrer\", toujours visible en bas de la page, confirme l'enregistrement (\"Annuler\" revient aux ordres tels qu'à l'ouverture de la page). Dans le Calendrier, un match aux ordres validés affiche \"Modifier vos ordres\".": "Przed każdym meczem ustaw trzy rzeczy dla swojej drużyny w zakładce Polecenia. Wszystko zapisuje się automatycznie przy każdej zmianie, a przycisk „Zapisz”, zawsze widoczny na dole strony, potwierdza zapis („Anuluj” przywraca polecenia do stanu z chwili otwarcia strony). W Terminarzu mecz z zatwierdzonymi poleceniami pokazuje „Zmień polecenia”.",
