  "Budget du club et son évolution, masse salariale (joueurs et staff), revenus de la salle, de la boutique et des droits TV, et l'historique des transactions groupé par semaine. Un budget durablement sous le seuil d'alerte finit par mettre tout l'effectif en vente forcée à 1 $ : surveillez la masse salariale.": "Budżet klubu i jego zmiany, suma pensji (zawodnicy i sztab), przychody z hali, sklepu i praw telewizyjnych oraz historia transakcji pogrupowana według tygodni. Budżet długo utrzymujący się poniżej progu alarmowego w końcu powoduje przymusową sprzedaż całego składu po 1 $: pilnuj sumy pensji.",
