  "Changement de couleurs de maillot extérieur refusé côté serveur.": "Zmiana kolorów stroju wyjazdowego odrzucona przez serwer.",
  "Changement de couleurs de maillot refusé côté serveur.": "Zmiana kolorów stroju odrzucona przez serwer.",
