  "Changement de maillot extérieur refusé côté serveur.": "Zmiana stroju wyjazdowego odrzucona przez serwer.",
  "Changement de maillot refusé côté serveur.": "Zmiana stroju odrzucona przez serwer.",
  "Changement de motif de maillot extérieur refusé côté serveur.": "Zmiana wzoru stroju wyjazdowego odrzucona przez serwer.",
  "Changement de motif de maillot refusé côté serveur.": "Zmiana wzoru stroju odrzucona przez serwer.",
