  "Changer de recruteur": "Zmień skauta",
  "Changer le logo": "Zmień logo",
  "Chaque annonce compare le prix à une valeur estimée (Bonne affaire, Prix correct, Au-dessus de sa valeur). Une enchère gagnée s'ajoute immédiatement à votre masse salariale : vérifiez votre budget avant de vous engager.": "Każde ogłoszenie porównuje cenę z szacowaną wartością (Okazja, Uczciwa cena, Powyżej swojej wartości). Wygrana licytacja od razu dolicza się do sumy pensji: sprawdź budżet, zanim się zaangażujesz.",
  "Chaque changement est déjà enregistré automatiquement. « Enregistrer » confirme l'enregistrement auprès du serveur.": "Każda zmiana jest już zapisywana automatycznie. „Zapisz” potwierdza zapis na serwerze.",
  "à chaque jour de repos (jour sans match) : soit préparer une nouvelle tactique, soit privilégier la récupération physique de l'équipe.": "w każdy dzień odpoczynku (dzień bez meczu): albo przygotować nową taktykę, albo postawić na regenerację fizyczną drużyny.",
  "Le club choisit": "Klub wybiera",
  "Chaque jour, le club travaille un programme parmi les 13 fondamentaux (tir à 3 points, rebond, défense extérieure...) et un ou plusieurs postes à qui l'appliquer. Cibler un seul poste donne le plein rendement ; l'étendre à toute l'équipe touche plus de joueurs mais dilue l'effet. Le Physique et le Mental évoluent, eux, tout seuls au fil de la carrière, indépendamment de ce programme.": "Każdego dnia klub realizuje jeden program spośród 13 umiejętności podstawowych (rzut za 3 punkty, zbiórka, obrona na obwodzie...) na jednej lub kilku wybranych pozycjach. Skupienie się na jednej pozycji daje pełną efektywność; rozszerzenie na całą drużynę obejmuje więcej zawodników, ale osłabia efekt. Fizyczność i Psychika rozwijają się natomiast same w trakcie kariery, niezależnie od tego programu.",
  "Chaque match se joue à son heure, que vous le regardiez ou non. Connecté, suivez-le depuis l'onglet": "Każdy mecz rozgrywa się o swojej porze, czy go oglądasz, czy nie. Gdy jesteś zalogowany, śledź go w zakładce",
  "Chaque nom de club doit être une chaîne non vide.": "Każda nazwa klubu musi być niepustym ciągiem.",
  "Chaque prospect affiche une estimation de potentiel (Espoir, Grand espoir ou Prodige) et se signe directement, sans enchère ni négociation, contrairement au marché des transferts.": "Każdy kandydat ma szacunkowy potencjał (Obiecujący, Wielki talent lub Cudowne dziecko) i podpisuje się go bezpośrednio, bez licytacji i negocjacji, w przeciwieństwie do rynku transferowego.",
  "Chaque variation d'ambiance est journalisée ici avec son motif exact : résultat de match, prix du billet, interview de jalon, demande de transfert, signal ou verdict d'objectif de saison.": "Każda zmiana nastroju jest tu zapisywana z dokładną przyczyną: wynik meczu, cena biletu, wywiad w kluczowym momencie, prośba o transfer, sygnał lub werdykt w sprawie celu sezonu.",
