  "Choisissez 3 priorités offensives pour les deux équipes avant le coup d'envoi.": "Wybierz 3 priorytety ofensywne dla obu drużyn przed rozpoczęciem meczu.",
  "Choisissez exactement 3 systèmes offensifs parmi 10 (Pick & Roll, Transition rapide, Post-up, Isolation...). Chacun modifie la répartition des tirs tentés (intérieur/mi-distance/3 points), les pertes de balle et le rythme.": "Wybierz dokładnie 3 systemy ofensywne spośród 10 (Pick & Roll, Szybki atak, Post-up, Izolacja...). Każdy zmienia rozkład oddawanych rzutów (spod kosza/z półdystansu/za 3 punkty), straty i tempo.",
