  "Congédiement du recruteur refusé côté serveur.": "Zwolnienie skauta odrzucone przez serwer.",
  "Congédiement du recruteur refusé.": "Zwolnienie skauta odrzucone.",
  "Congédier": "Zwolnij",
  "Connaissance tactique": "Wiedza taktyczna",
  "Connaissance tactique : chaque option jouée monte de +6 à +12 par match, +4 par jour d'entraînement dessus ; une option délaissée ne baisse qu'à partir du 3e match d'absence (-2, -4, puis -6 au maximum). Le détail est dans le Guide.": "Wiedza taktyczna: każda grana opcja rośnie o +6 do +12 na mecz, +4 za każdy dzień treningu nad nią; zaniedbana opcja spada dopiero od 3. meczu nieobecności (-2, -4, potem maksymalnie -6). Szczegóły znajdziesz w Przewodniku.",
  "Conseil : attaquez la raquette sans crainte, pénétrez et finissez au panier plutôt que de vous contenter du tir extérieur.": "Rada: atakuj pomalowane bez obaw, wchodź pod kosz i kończ akcje zamiast zadowalać się rzutami z dystansu.",
  "Conseil : envoyez du monde au rebond offensif, les secondes chances seront disponibles.": "Rada: wysyłaj ludzi na zbiórkę w ataku, będą drugie szanse.",
  "Conseil : évitez la finition en force au cercle, privilégiez le tir extérieur ou la passe après pénétration (kick-out) plutôt que le layup contesté.": "Rada: unikaj forsowania akcji pod koszem, wybieraj rzut z dystansu albo podanie po wejściu (kick-out) zamiast kontestowanego lay-upu.",
  "Conseil : forcez la pénétration balle en main et jouez agressif vers le cercle pour provoquer des fautes et aller sur la ligne des lancers francs.": "Rada: forsuj wejścia z piłką i graj agresywnie pod kosz, żeby wymuszać faule i stawać na linii rzutów wolnych.",
  "Conseil : ne comptez pas sur les lancers francs, il faudra scorer au jeu plutôt que provoquer la faute.": "Rada: nie licz na rzuty wolne, trzeba będzie punktować z gry zamiast wymuszać faule.",
  "Conseil : ne surinvestissez pas le rebond offensif, repliez-vous plus tôt pour limiter leur contre-attaque.": "Rada: nie przesadzaj ze zbiórką w ataku, wracaj wcześniej do obrony, żeby ograniczyć ich kontry.",
  "Conseil : sécurisez la balle et limitez les passes risquées pour ne pas les lancer en contre-attaque.": "Rada: dbaj o piłkę i ograniczaj ryzykowne podania, żeby nie napędzać ich kontrataków.",
