  "Contrôlé est le réglage neutre. Agressif conteste mieux les tirs extérieurs réellement pris, mais une fermeture trop appuyée ouvre plus facilement la pénétration : le tireur en profite pour foncer vers le panier plutôt que de tirer.": "Kontrolowany to ustawienie neutralne. Agresywny lepiej kontestuje faktycznie oddawane rzuty z dystansu, ale zbyt mocne doskoki ułatwiają minięcie: strzelec wykorzystuje to, by ruszyć pod kosz zamiast rzucać.",
