  "Fixe": "Stała pensja",
  "Fixé par le conseil d'administration en tout début de saison, d'après le niveau de votre effectif face au reste du championnat. Deux signaux intermédiaires (mi-saison, puis juste après la fin de la saison régulière) réagissent déjà à votre rythme actuel, avant le verdict final, plus marqué, une fois la saison bouclée.": "Ustalany przez zarząd na samym początku sezonu na podstawie poziomu twojego składu w porównaniu z resztą ligi. Dwa sygnały pośrednie (w połowie sezonu, a potem tuż po zakończeniu sezonu zasadniczego) reagują już na twoje obecne tempo, zanim zapadnie ostateczny, bardziej zdecydowany werdykt po zakończeniu sezonu.",
