  "JSON invalide.": "Nieprawidłowy JSON.",
  "Jusqu'à 150 000 $": "Do 150 000 $",
  "Jusqu'à 3 affectations poste + focus (empêcher le post-up, coller sur les pénétrations, harceler le tir extérieur, priorité au rebond, couper du ballon). Chaque focus donne un bonus défensif ciblé, avec une petite contrepartie ailleurs pour le défenseur concerné.": "Do 3 przydziałów pozycja + priorytet (blokuj grę tyłem do kosza, kryj ciasno przy wejściach, nękaj rzuty z dystansu, priorytet zbiórki, ścinaj bez piłki). Każdy priorytet daje ukierunkowany bonus defensywny, z niewielkim kosztem w innym aspekcie dla danego obrońcy.",
  "Jusqu'à 300 000 $": "Do 300 000 $",
  "Jusqu'à 50 000 $": "Do 50 000 $",
  "Jusqu'où le joueur peut encore progresser, jamais en chiffre : un palier parmi 10, de Débutant à Générationnel (Prospect, Joueur correct, Solide, Starter, Très bon joueur, Star, All-Star, Superstar). Les jeunes de l'académie n'affichent qu'une estimation : Espoir, Grand espoir ou Prodige.": "Jak daleko zawodnik może jeszcze się rozwinąć, nigdy w liczbach: jeden poziom spośród 10, od Początkującego do Pokoleniowego (Obiecujący, Przyzwoity zawodnik, Solidny, Starter, Bardzo dobry zawodnik, Gwiazda, All-Star, Supergwiazda). Juniorzy z akademii pokazują tylko szacunek: Talent, Wielki talent lub Cudowne dziecko.",
  "Kante": "Kante",
  "Karim": "Karim",
  "Keita": "Keita",
  "Kelly": "Kelly",
  "Kevin": "Kevin",
  "kicker": "kicker",
  "kickoff": "kickoff",
  "Kobayashi": "Kobayashi",
  "Kone": "Kone",
  "Kovac": "Kovac",
  "Kowalski": "Kowalski",
  "l'adversaire": "rywal",
  "L'adversaire ne peut pas aligner un cinq de départ complet : vous gagnerez automatiquement par forfait (20-0) à l'heure prévue.": "Rywal nie może wystawić pełnej pierwszej piątki: automatycznie wygrasz walkowerem (20-0) o zaplanowanej godzinie.",
  "L’affiche": "Hit kolejki",
  "L'alchimie (40 à 100, visible sur le Tableau de bord et en tête de l'Effectif) mesure la cohésion du groupe. Elle agit sur TOUTE l'équipe en match, de -6 % (vestiaire fracturé) à +6 % (alchimie parfaite). Paliers : Vestiaire fracturé (moins de 48), Tensions dans le groupe (48-59), Cohésion correcte (60-73), Bonne cohésion (74-87), Alchimie parfaite (88 et plus).": "Chemia (od 40 do 100, widoczna na Pulpicie i na górze Składu) mierzy zgranie grupy. Wpływa na CAŁĄ drużynę w meczu, od -6% (podzielona szatnia) do +6% (idealna chemia). Progi: Podzielona szatnia (poniżej 48), Napięcia w grupie (48-59), Przyzwoite zgranie (60-73), Dobre zgranie (74-87), Idealna chemia (88 i więcej).",
  "L'ambiance du club": "Atmosfera w klubie",
  "L’attaque tourne à plein régime.": "Atak działa na pełnych obrotach.",
  "L’AVANT-": "PRZED",
  "L’AVANT-MATCH": "PRZED MECZEM",
  "L'effectif jeunes est déjà complet (15 stagiaires).": "Kadra juniorów jest już pełna (15 adeptów).",
  "L'émission de la mi-temps": "Program w przerwie",
  "l'emporte de": "wygrywa różnicą",
  "L'entraîneur n'a aucun effet sur les matchs : il accélère uniquement la progression à l'entraînement (+6% par niveau). On ne l'achète plus à prix fixe : plusieurs candidats de niveaux variés sont proposés en permanence sur un": "Trener nie ma żadnego wpływu na mecze: przyspiesza jedynie postępy na treningach (+6% na poziom). Nie kupuje się go już po stałej cenie: kilku kandydatów o różnych poziomach jest stale dostępnych na",
  "L'entre-deux est remporté par {0}.": "Rzut sędziowski wygrywa {0}.",
  "L'humeur des supporters (0 à 100, onglet dédié) influence le remplissage de votre salle et la tolérance au prix du billet : des supporters contents viennent plus facilement et acceptent des prix plus élevés. Elle évolue avec chaque résultat (victoire ou défaite, à domicile ou à l'extérieur), vos tons en interview de jalon, et dérive lentement selon que le prix des billets est jugé raisonnable ou non.": "Nastrój kibiców (od 0 do 100, osobna zakładka) wpływa na zapełnienie twojej hali i tolerancję na ceny biletów: zadowoleni kibice chętniej przychodzą i akceptują wyższe ceny. Zmienia się po każdym wyniku (zwycięstwo lub porażka, u siebie lub na wyjeździe), w zależności od tonu w wywiadach po kamieniach milowych, i powoli dryfuje w zależności od tego, czy ceny biletów są uznawane za rozsądne.",
  "L'image de votre salle actuelle. Une salle plus grande accueille plus de spectateurs à chaque match à domicile, donc plus de recettes de billetterie.": "Obraz twojej obecnej hali. Większa hala mieści więcej widzów na każdym meczu u siebie, a więc daje większe wpływy z biletów.",
  "L'objectif de saison": "Cel na sezon",
  "L'objectif est clair pour cette saison : on vise le haut de tableau, on ne se fixe aucune limite.": "Cel na ten sezon jest jasny: celujemy w czołówkę tabeli i nie stawiamy sobie żadnych ograniczeń.",
  "L'objectif est de construire une équipe solide et de rester compétitifs sur la durée de la saison, sans se fixer de chiffre précis pour l'instant.": "Celem jest zbudowanie solidnej drużyny i utrzymanie konkurencyjności przez cały sezon, na razie bez wyznaczania konkretnej liczby.",
  "L'onglet": "Zakładka",
  "La": "​",
  "La confiance du joueur, jamais liée à la fatigue. Alimentée par le ton choisi lors des interviews de jalon (voir l'onglet Humeur des supporters) : Agressif amplifie le résultat, Mesuré reste modéré, Humble limite la casse en cas de défaite.": "Pewność siebie zawodnika, nigdy niezwiązana ze zmęczeniem. Zależy od tonu wybranego w wywiadach po kamieniach milowych (zob. zakładkę Nastrój kibiców): Agresywny wzmacnia efekt wyniku, Wyważony pozostaje umiarkowany, Skromny ogranicza straty w razie porażki.",
  "La Coupe": "Puchar",
  "La Coupe n'existe que pour la ligue multi-manager (elle n'est pas jouée en carrière solo pour l'instant).": "Puchar istnieje tylko w lidze wielu menedżerów (na razie nie jest rozgrywany w karierze solo).",
  "La courbe apparaîtra après le premier événement.": "Wykres pojawi się po pierwszym wydarzeniu.",
  "La courbe du budget apparaîtra après la première semaine.": "Wykres budżetu pojawi się po pierwszym tygodniu.",
  "La décision à 18 ans": "Decyzja w wieku 18 lat",
  "la défaite": "porażka",
  "La feuille de match": "Skład na mecz",
  "La feuille de match de l'adversaire est incomplète : vous gagnerez par forfait (20-0) si elle n'est pas réglée avant le coup d'envoi.": "Skład na mecz rywala jest niekompletny: wygrasz walkowerem (20-0), jeśli nie zostanie uzupełniony przed początkiem meczu.",
  "la finale des play-offs": "finał play-offów",
  "La ligue": "Liga",
  "LA LIGUE": "LIGA",
  "La ligue est lancée : première journée vendredi à {0}.": "Liga wystartowała: pierwsza kolejka w piątek o {0}.",
  "La liste des jeunes formés dans votre académie qui sont ensuite passés pro : un aperçu de ce que votre filière de formation a déjà produit pour le club.": "Lista juniorów wyszkolonych w twojej akademii, którzy potem przeszli na zawodowstwo: podgląd tego, co twoje szkolenie młodzieży już dało klubowi.",
  "La plupart des joueurs se situent dans les paliers médians (Starter à All-Star) ; Superstar et Générationnel restent volontairement rares.": "Większość zawodników mieści się w środkowych poziomach (od Startera do All-Stara); Supergwiazda i Pokoleniowy pozostają celowo rzadkie.",
  "La routine conseillée avant chaque match : vérifier la forme des joueurs (": "Zalecana rutyna przed każdym meczem: sprawdź formę zawodników (",
