  "Le": "​",
  "Le barrage de relégation a été calculé. Les play-offs commencent, un match à la fois, en direct, sur plusieurs jours réels.": "Baraż o utrzymanie został rozliczony. Rozpoczynają się play-offy, mecz po meczu, na żywo, przez kilka rzeczywistych dni.",
  "Le calendrier": "Terminarz",
  "Le calendrier sera généré pour les clubs déjà inscrits.": "Terminarz zostanie wygenerowany dla już zapisanych klubów.",
  "Le centre de formation": "Akademia",
  "Le champion est désormais connu, direction l'écran de fin de saison.": "Mistrz jest już znany, przechodzimy do ekranu końca sezonu.",
  "Le championnat est lancé": "Rozgrywki ligowe wystartowały",
  "Le classement avant la journée": "Tabela przed kolejką",
  "Le classement s'affichera après les premiers matchs de championnat.": "Tabela pojawi się po pierwszych meczach ligowych.",
  "Le classement se départage par victoires puis par différence de points. Il est découpé en zones : places 1 à 4 qualifiées pour les": "O kolejności w tabeli decydują zwycięstwa, a potem różnica punktów. Jest podzielona na strefy: miejsca 1–4 dają awans do",
  "Le classement se départage par victoires puis par différence de points. Places 1 à 4 : play-offs ; 5 et 6 : maintien ; 7 et 8 : barrage ; 9 et 10 : relégation. Ce panneau résume votre position et l'écart avec les places clés.": "O kolejności w tabeli decydują zwycięstwa, a potem różnica punktów. Miejsca 1–4: play-offy; 5. i 6.: utrzymanie; 7. i 8.: baraż; 9. i 10.: spadek. Ten panel podsumowuje twoją pozycję i dystans do kluczowych miejsc.",
  "Le club est en quasi-faillite (budget : {0}, sous {1} depuis {2} semaine(s)) : tout l'effectif a été mis en vente forcée à 1 $. Direction l'onglet": "Klub jest na skraju bankructwa (budżet: {0}, poniżej {1} od {2} tyg.): cały skład został przymusowo wystawiony na sprzedaż za 1 $. Przejdź do zakładki",
  "Le club est entre vos mains. Bonne saison, coach.": "Klub jest w twoich rękach. Udanego sezonu, trenerze.",
  "Le coup d'envoi est imminent.": "Początek meczu tuż-tuż.",
  "Le duel à suivre": "Pojedynek do obserwowania",
  "Le duel de la soirée : {a} contre {b}.": "Pojedynek wieczoru: {a} kontra {b}.",
  "Le Hall of Fame est plein ({0} joueurs).": "Hall of Fame jest pełna ({0} zawodników).",
  "Le joueur": "Zawodnik",
  "Le journal des événements": "Dziennik wydarzeń",
  "Le marché des transferts": "Rynek transferowy",
  "Le match à suivre": "Mecz do obserwowania",
  "le match précédent": "poprzedni mecz",
  "Le même Centre de formation que dans l'onglet Salle, mais géré directement ici : agrandissable palier par palier, il accélère la progression automatique de tous vos jeunes tant qu'ils ont moins de 18 ans.": "Ta sama Akademia co w zakładce Hala, ale zarządzana bezpośrednio tutaj: rozbudowywana poziom po poziomie, przyspiesza automatyczny rozwój wszystkich twoich juniorów, dopóki mają mniej niż 18 lat.",
  "Le moteur vise ces minutes et les ajuste seul en cas de blessure, de fautes ou de fatigue. Un poste en automatique garde la rotation habituelle.": "Silnik dąży do tych minut i sam je dostosowuje w razie kontuzji, fauli lub zmęczenia. Pozycja ustawiona na automatyczną zachowuje zwykłą rotację.",
  "Le n°1 en fin de saison gagne 1 mois de Premium": "Nr 1 na koniec sezonu wygrywa 1 miesiąc Premium",
  "Le nom de la ligue doit faire entre 2 et {0} caractères.": "Nazwa ligi musi mieć od 2 do {0} znaków.",
  "Le nom de la salle contient des caractères non autorisés.": "Nazwa hali zawiera niedozwolone znaki.",
  "Le nom de la salle doit faire entre 3 et {0} caractères.": "Nazwa hali musi mieć od 3 do {0} znaków.",
  "Le nom et la capacité de votre salle actuelle, avec un bouton Agrandir pour passer au palier suivant quand vous en avez les moyens (8 paliers en tout, du Petit gymnase à l'Arena nationale).": "Nazwa i pojemność twojej obecnej hali, z przyciskiem Rozbuduj, aby przejść na kolejny poziom, gdy będzie cię na to stać (łącznie 8 poziomów, od Małej sali gimnastycznej do Areny narodowej).",
  "Le numéro {0} est déjà retiré.": "Numer {0} jest już zastrzeżony.",
  "Le poste de {poste} est désormais pourvu.": "Pozycja {poste} jest już obsadzona.",
  "Le potentiel indique jusqu'où un joueur peut encore progresser, pas sa qualité du moment. Il ne s'affiche jamais en chiffre : seulement un": "Potencjał pokazuje, jak daleko zawodnik może się jeszcze rozwinąć, a nie jego obecną jakość. Nigdy nie jest wyświetlany jako liczba: tylko",
  "Le prix des billets se règle depuis l'onglet Salle, pas ici : ajustez-le pour équilibrer affluence et recettes.": "Ceny biletów ustawiasz w zakładce Hala, nie tutaj: dostosuj je, by zrównoważyć frekwencję i wpływy.",
  "Le roster complet du club en une seule liste, cinq de départ en tête, puis rotation et réserve : poste, potentiel, âge, salaire, forme, motivation et évaluation des derniers matchs. Cliquez sur un nom pour ouvrir la fiche du joueur (caractéristiques, saison, Comparer, Vendre).": "Pełny skład klubu na jednej liście, najpierw pierwsza piątka, potem rotacja i rezerwa: pozycja, potencjał, wiek, pensja, forma, motywacja i ocena z ostatnich meczów. Kliknij nazwisko, aby otworzyć profil zawodnika (cechy, sezon, Porównaj, Sprzedaj).",
  "Le serveur a refusé ce nom.": "Serwer odrzucił tę nazwę.",
  "Le serveur a refusé ce trigramme.": "Serwer odrzucił ten skrót.",
  "Le serveur a refusé de charger la carrière :": "Serwer odmówił wczytania kariery:",
