  "le titre de champion": "tytuł mistrzowski",
  "Le total sera ramené à 40 min en gardant ces proportions.": "Suma zostanie sprowadzona do 40 min z zachowaniem tych proporcji.",
  "Le travail à l'entraînement toute la semaine a payé ce soir, je suis content d'avoir pu répondre présent.": "Praca na treningach przez cały tydzień opłaciła się dziś wieczorem, cieszę się, że stanąłem na wysokości zadania.",
  "Le trigramme doit faire 2 ou 3 lettres (A-Z).": "Skrót musi mieć 2 lub 3 litery (A-Z).",
  "Le vrai potentiel d'un jeune reste caché derrière une estimation à 3 paliers jusqu'à sa promotion : la décision comporte donc une part de pari.": "Prawdziwy potencjał juniora pozostaje ukryty za 3-stopniową oceną aż do awansu: decyzja jest więc po części zakładem.",
