  "Lent, Normal ou Rapide : fixe le nombre de possessions jouées, donc le nombre d'occasions de marquer de chaque côté.": "Wolne, Normalne lub Szybkie: ustala liczbę rozgrywanych posiadań, a więc liczbę okazji do zdobycia punktów po obu stronach.",
