  "Les ligues privées n'existent que dans la ligue partagée entre managers (pas en carrière solo).": "Ligi prywatne istnieją tylko w lidze wspólnej dla menedżerów (nie w karierze solo).",
  "Les ligues privées ne sont disponibles que dans la ligue partagée.": "Ligi prywatne są dostępne tylko we wspólnej lidze.",
  "Les ligues privées sont réservées aux clubs Premium.": "Ligi prywatne są zarezerwowane dla klubów Premium.",
  "Les noms de club doivent être uniques.": "Nazwy klubów muszą być unikalne.",
  "Les ordres de Coupe se préparent comme ceux du championnat, depuis le Calendrier ou le sélecteur de journée de la page Ordres.": "Polecenia na Puchar przygotowuje się tak samo jak ligowe, z Terminarza lub selektora kolejki w zakładce Polecenia.",
  "Les play-offs sont en cours, sur plusieurs jours réels. Revenez pour votre prochain match, ou suivez leur progression ici.": "Play-offy trwają przez kilka rzeczywistych dni. Wróć na swój następny mecz albo śledź ich przebieg tutaj.",
  "Les play-offs vont commencer.": "Play-offy zaraz się zaczną.",
  "Les records s'écriront dès le premier match joué.": "Rekordy zaczną się zapisywać od pierwszego rozegranego meczu.",
  "Le poste d'un joueur suit ses caractéristiques : dès que sa note à un autre poste dépasse nettement celle de son poste actuel, il change de poste (une nouvelle vous prévient). Les salaires (masse salariale visible sur l'onglet": "Pozycja zawodnika zależy od jego cech: gdy tylko jego ocena na innej pozycji wyraźnie przewyższy ocenę na obecnej, zmienia pozycję (powiadomi cię o tym wiadomość). Pensje (łączne płace widoczne w zakładce",
  "Les sponsors reviennent tous les 3 jours. Une meilleure réputation attire de plus grandes marques.": "Sponsorzy wracają co 3 dni. Lepsza reputacja przyciąga większe marki.",
  "Les statistiques de ligue privée ne comptent ni dans les stats de carrière ni dans le classement des joueurs.": "Statystyki z ligi prywatnej nie liczą się ani do statystyk kariery, ani do rankingu zawodników.",
