  "liste tous vos matchs de la saison, championnat et Coupe confondus, groupés par mois et triés par date et heure réelle. Filtres Tous, Domicile, Extérieur et À venir ; \"vs\" devant l'adversaire signifie à domicile, \"@\" à l'extérieur. À droite : la carte du prochain match (compte à rebours et bouton des ordres) et le bilan de la saison (bilan, classement, différence de points, domicile/extérieur, forme sur les 5 derniers matchs). Les horaires restent fixes, même au changement d'heure.": "pokazuje wszystkie twoje mecze w sezonie, ligowe i pucharowe razem, pogrupowane według miesięcy i posortowane według rzeczywistej daty i godziny. Filtry Wszystkie, U siebie, Na wyjeździe i Nadchodzące; „vs” przed rywalem oznacza mecz u siebie, „@” na wyjeździe. Po prawej: karta następnego meczu (odliczanie i przycisk poleceń) oraz podsumowanie sezonu (bilans, tabela, różnica punktów, u siebie/na wyjeździe, forma z ostatnich 5 meczów). Godziny pozostają stałe, nawet przy zmianie czasu.",
