  "Mental": "Psychika",
  "MENTAL": "PSYCHIKA",
  "Mental, Endurance, Lancer franc, Puissance, Concentration, Anticipation et Leadership alimentent chacune un mécanisme de match dédié. Le Mental améliore la réussite au tir dans le money time et limite les dégâts d'une mauvaise série. L'Endurance ralentit la fatigue EN MATCH du joueur. Le Lancer franc détermine directement la réussite aux lancers francs, la Concentration l'améliore encore un peu. La Puissance augmente les fautes provoquées près du panier. L'Anticipation renforce la pression défensive de toute l'équipe sur les extérieurs. Le Leadership du MEILLEUR joueur du cinq en jeu allège, pour toute l'équipe, le malus d'une mauvaise série de tirs manqués.": "Psychika, Wytrzymałość, Rzut wolny, Siła fizyczna, Koncentracja, Antycypacja i Przywództwo zasilają każda osobny mechanizm meczowy. Psychika poprawia skuteczność rzutów w końcówce meczu i ogranicza skutki złej serii. Wytrzymałość spowalnia zmęczenie zawodnika W TRAKCIE MECZU. Rzut wolny bezpośrednio decyduje o skuteczności rzutów wolnych, a Koncentracja jeszcze nieco ją poprawia. Siła fizyczna zwiększa liczbę fauli wymuszonych blisko kosza. Antycypacja wzmacnia presję defensywną całej drużyny na obwodzie. Przywództwo NAJLEPSZEGO zawodnika z piątki na boisku łagodzi, dla całej drużyny, karę za złą serię niecelnych rzutów.",
  "mentalAvg": "mentalAvg",
