  "Nom de la salle enregistré : {0}.": "Nazwa hali zapisana: {0}.",
  "Nom, poste, taille et salaire des joueurs adverses sont toujours visibles, mais leurs caractéristiques restent cachées tant qu'elles n'ont pas été révélées : l'onglet Caractéristiques de l'effectif adverse n'affiche QUE les caracs révélées. Recrutez un": "Imię, pozycja, wzrost i pensja zawodników rywala są zawsze widoczne, ale ich cechy pozostają ukryte, dopóki nie zostaną odkryte: zakładka Cechy składu rywala pokazuje TYLKO odkryte cechy. Zatrudnij",
