  "Nouvelle faute antisportive pour {player} ({team}) : cumul de fautes disciplinaires, exclusion !": "Kolejny faul niesportowy {player} ({team}): suma przewinień dyscyplinarnych, wykluczenie!",
  "Nouvelle faute technique pour {player} ({team}) : cumul de fautes disciplinaires, exclusion !": "Kolejny faul techniczny {player} ({team}): suma przewinień dyscyplinarnych, wykluczenie!",
  "Nouvelle saison : les salaires ont été réévalués selon le niveau actuel de chaque joueur.": "Nowy sezon: pensje zostały przeliczone według obecnego poziomu każdego zawodnika.",
