  "Nunes": "Nunes",
  "O'Brien": "O'Brien",
  "Objectif de la saison largement dépassé ({0} espéré) : l'équipe termine avec {1} ! Les supporters sont aux anges.": "Cel sezonu wyraźnie przekroczony (oczekiwano: {0}): drużyna kończy z wynikiem {1}! Kibice są zachwyceni.",
  "Objectif de la saison manqué ({0}) : l'équipe termine avec {1}. Les supporters sont déçus.": "Cel sezonu nieosiągnięty ({0}): drużyna kończy z wynikiem {1}. Kibice są rozczarowani.",
  "Objectif de la saison manqué ({0}) : l'équipe termine avec une relégation. Les supporters sont déçus. ({1}).": "Cel sezonu nieosiągnięty ({0}): drużyna kończy sezon spadkiem. Kibice są rozczarowani. ({1}).",
  "Objectif de la saison rempli ({0}) : l'équipe termine avec {1}, exactement ce qui était demandé.": "Cel sezonu osiągnięty ({0}): drużyna kończy z wynikiem {1}, dokładnie tak, jak oczekiwano.",
  "Objectif de saison": "Cel sezonu",
  "Objectif du CA": "Cel zarządu",
  "Objectif du conseil": "Cel zarządu",
  "Objectif du sponsor": "Cel sponsora",
  "oddStat": "oddStat",
  "off": "off",
  "offense": "offense",
  "offensivePriorities doit être un tableau non vide.": "offensivePriorities musi być niepustą tablicą.",
  "offer_closed": "offer_closed",
  "offer_received": "offer_received",
  "offre": "Oferta",
  "Offre de sponsor : {0}": "Oferta sponsorska: {0}",
  "Offre reçue pour {joueur}": "Otrzymano ofertę za {joueur}",
  "Offre refusée.": "Oferta odrzucona.",
  "offRebStyle": "offRebStyle",
  "Offres reçues": "Otrzymane oferty",
  "ok": "ok",
  "Oliveira": "Oliveira",
  "on": "on",
  "On a fait la moitié du chemin avec cette victoire contre {opponent}, mais rien n'est acquis, il reste encore beaucoup de travail avant la fin de saison.": "Tym zwycięstwem nad {opponent} jesteśmy w połowie drogi, ale nic nie jest przesądzone, do końca sezonu zostało jeszcze mnóstwo pracy.",
  "On aborde la suite avec humilité, chaque adversaire mérite le plus grand respect à ce stade de la saison.": "Do dalszej części podchodzimy z pokorą, każdy rywal na tym etapie sezonu zasługuje na najwyższy szacunek.",
  "On aborde la suite avec l'envie de corriger ce qui n'a pas fonctionné ces dernières semaines.": "Do dalszej części podchodzimy z chęcią poprawienia tego, co nie działało w ostatnich tygodniach.",
  "On aborde la suite avec la certitude d'avoir le niveau pour aller loin, sans aucune pression particulière.": "Do dalszej części podchodzimy z przekonaniem, że mamy poziom, by zajść daleko, bez żadnej szczególnej presji.",
  "On aborde la suite avec la même confiance, cette fin de saison régulière ne change rien à nos ambitions.": "Do dalszej części podchodzimy z tą samą pewnością siebie, ten koniec sezonu zasadniczego nie zmienia naszych ambicji.",
  "On aborde la suite en sachant qu'il reste beaucoup de travail, on ne change rien à notre état d'esprit.": "Do dalszej części podchodzimy ze świadomością, że czeka nas jeszcze dużo pracy, nie zmieniamy nastawienia.",
  "On aborde la suite sereinement, en essayant de garder cette dynamique le plus longtemps possible.": "Do dalszej części podchodzimy spokojnie, starając się jak najdłużej utrzymać tę dobrą passę.",
  "On accepte cette élimination avec humilité et on va travailler encore plus dur pour revenir plus forts.": "Przyjmujemy to odpadnięcie z pokorą i będziemy pracować jeszcze ciężej, żeby wrócić silniejsi.",
  "On cherche un partenaire stable, pas un feu de paille.": "Szukamy stabilnego partnera, a nie słomianego zapału.",
  "On compte énormément sur {player} pour tirer l'équipe vers le haut, c'est un joueur fait pour ce genre de responsabilités.": "Bardzo liczymy na {player}, że pociągnie drużynę w górę, to zawodnik stworzony do takiej odpowiedzialności.",
  "On doit se remettre en question collectivement et travailler encore plus dur pour la seconde moitié de saison.": "Musimy wspólnie zrobić rachunek sumienia i pracować jeszcze ciężej w drugiej połowie sezonu.",
  "On envoie un message clair à toute la ligue en éliminant {opponent} en demi-finale, la prochaine étape ne nous fait absolument pas peur.": "Eliminując {opponent} w półfinale, wysyłamy jasny sygnał całej lidze — następny krok zupełnie nas nie przeraża.",
  "On ne se fixe pas d'objectif chiffré, l'idée est de progresser ensemble match après match, en restant les pieds sur terre.": "Nie wyznaczamy sobie liczbowego celu, chodzi o to, by rozwijać się razem mecz po meczu i twardo stąpać po ziemi.",
  "On passe le cap de la mi-saison sur la meilleure dynamique possible, et {opponent} vient encore de le confirmer : personne ne veut vraiment nous affronter en ce moment.": "Przekraczamy półmetek sezonu w najlepszej możliwej formie, a {opponent} właśnie znów to potwierdził: nikt nie chce teraz z nami grać.",
  "On prépare la suite avec la même confiance, on n'a pas fait tout ce chemin pour s'arrêter en si bon chemin.": "Przygotowujemy się do dalszej części z tą samą pewnością siebie, nie przeszliśmy tak długiej drogi, żeby teraz się zatrzymać.",
  "On savait qu'on était la meilleure équipe de la division, ce titre face à {opponent} en finale ne fait que le confirmer.": "Wiedzieliśmy, że jesteśmy najlepszą drużyną w dywizji, ten tytuł wywalczony w finale z {opponent} tylko to potwierdza.",
  "On se retrouve après une courte pause…": "Do zobaczenia po krótkiej przerwie…",
  "On termine la saison régulière sur cette victoire contre {opponent}, et on aborde les échéances qui arrivent avec la plus grande confiance qui soit.": "Kończymy sezon zasadniczy zwycięstwem nad {opponent} i do nadchodzących wyzwań podchodzimy z ogromną pewnością siebie.",
  "On termine la saison régulière sur une défaite décevante contre {opponent}, mais le bilan global de l'année reste ce qui compte le plus.": "Kończymy sezon zasadniczy rozczarowującą porażką z {opponent}, ale najważniejszy jest ogólny bilans roku.",
  "On tire un trait sur cette élimination et on prépare déjà la revanche pour la saison prochaine, sans complexe.": "Zamykamy temat tego odpadnięcia i już szykujemy rewanż w przyszłym sezonie, bez kompleksów.",
  "On va analyser calmement cette élimination et en tirer les enseignements pour progresser encore.": "Na spokojnie przeanalizujemy to odpadnięcie i wyciągniemy wnioski, by dalej się rozwijać.",
  "On va continuer à travailler dans la continuité, avec quelques ajustements tactiques pour la seconde moitié.": "Będziemy dalej pracować w ten sam sposób, z kilkoma korektami taktycznymi na drugą połowę.",
  "On va continuer à travailler humblement, rien n'est jamais acquis dans ce championnat.": "Będziemy dalej pracować z pokorą, w tej lidze nic nie jest dane raz na zawsze.",
  "On va préparer la suite avec sérieux, sans s'enflammer, il reste encore une marche à franchir.": "Przygotujemy się do dalszej części na poważnie, bez hurraoptymizmu, został jeszcze jeden stopień do pokonania.",
  "On va préparer la suite pas à pas, sans se projeter trop vite sur la suite.": "Będziemy przygotowywać się krok po kroku, bez wybiegania zbyt daleko w przyszłość.",
  "On va revoir certains détails à l'entraînement pour repartir sur de meilleures bases en seconde moitié de saison.": "Przejrzymy pewne szczegóły na treningach, żeby zacząć drugą połowę sezonu z lepszej pozycji.",
  "On veut vous voir plus haut que ce que le CA demande.": "Chcemy widzieć cię wyżej, niż oczekuje zarząd.",
  "On vous suit sur l'objectif de la saison.": "Śledzimy twoje postępy w realizacji celu sezonu.",
