  "Pas assez de ventes comparables (même poste, note globale proche) ces 60 derniers jours pour une estimation.": "Za mało porównywalnych transakcji (ta sama pozycja, podobna ocena ogólna) w ostatnich 60 dniach, by oszacować wartość.",
  "Pas d'entraînement": "Brak treningu",
  "Pas de changement visible cette semaine, la progression est lente et se joue sur plusieurs semaines.": "Brak widocznej zmiany w tym tygodniu, rozwój jest powolny i trwa kilka tygodni.",
