  "Pas encore assez de caractéristiques révélées pour un rapport de scouting (faites une séance vidéo pour en débloquer).": "Za mało odkrytych cech, by sporządzić raport skautingowy (zrób sesję wideo, by je odblokować).",
  "Pas encore assez de données sur cet adversaire pour préremplir tes ordres.": "Za mało danych o tym rywalu, by wstępnie uzupełnić twoje polecenia.",
