  "Passez en Confirmé dès que vous voulez affiner un point précis (par exemple neutraliser le pivot adverse) : les réglages suivants apparaissent alors.": "Przełącz na tryb Zaawansowany, gdy chcesz dopracować konkretny element (np. zneutralizować środkowego rywala): wtedy pojawią się poniższe ustawienia.",
