  "penetration": "penetration",
  "Pénétration": "Penetracja",
  "Pénétration, Création de tir, Interceptions, Vitesse, Accélération, Force, Détente, Décision, Sang-froid, Détermination, Discipline et Vision ont elles aussi leur mécanisme. La Pénétration aide à se créer un accès à la raquette. La Création de tir est le facteur principal de la qualité d'ouverture d'un tir. Les Interceptions pèsent dans le choix du voleur de balle. La Vitesse et l'Accélération déclenchent des contre-attaques et aident à battre son défenseur au premier pas. La Force et la Détente renforcent le rebond et le contre. La Décision réduit les pertes de balle ; la Vision améliore le choix du passeur. Le Sang-froid et la Détermination agissent comme le Mental. La Discipline réduit les fautes en défense ; un défenseur peu discipliné risque une faute antisportive, un défenseur peu serein une faute technique : deux techniques, deux antisportives, ou une de chaque dans le même match valent exclusion.": "Penetracja, Kreowanie rzutu, Przechwyty, Szybkość, Przyspieszenie, Siła, Wyskok, Podejmowanie decyzji, Opanowanie, Determinacja, Dyscyplina i Wizja również mają swoje mechanizmy. Penetracja pomaga dostać się pod kosz. Kreowanie rzutu to główny czynnik decydujący o tym, jak czysta jest pozycja rzutowa. Przechwyty wpływają na to, kto przechwyci piłkę. Szybkość i Przyspieszenie napędzają kontrataki i pomagają minąć obrońcę pierwszym krokiem. Siła i Wyskok wzmacniają zbiórki i bloki. Podejmowanie decyzji ogranicza straty; Wizja poprawia wybór podającego. Opanowanie i Determinacja działają jak Psychika. Dyscyplina ogranicza faule w obronie; mało zdyscyplinowany obrońca ryzykuje faul niesportowy, a mało opanowany — faul techniczny: dwa techniczne, dwa niesportowe albo po jednym z każdego w tym samym meczu oznaczają wykluczenie.",
