  "Chaque poste a sa carte sur le terrain : titulaire, remplaçant et réserviste. Les alertes (joueur hors poste, remplaçant plus fort que le titulaire, joueur aligné à deux postes) s'affichent directement sur la carte, et la liste de l'effectif à côté sert à convoquer les 12 joueurs du match.": "Każda pozycja ma swoją kartę na boisku: podstawowy, rezerwowy i zapasowy. Ostrzeżenia (zawodnik poza pozycją, rezerwowy lepszy od podstawowego, zawodnik wpisany na dwóch pozycjach) wyświetlają się bezpośrednio na karcie, a lista składu obok służy do powołania 12 zawodników na mecz.",
