  "Récap": "Bilans",
  "Récapitulatif semaine par semaine de votre club : matchs joués et performances individuelles de l'effectif. Naviguez d'une semaine à l'autre avec les flèches en haut de la page. Les finances sont dans l'onglet Économie, l'humeur des supporters dans son propre onglet.": "Tydzień po tygodniu podsumowanie twojego klubu: rozegrane mecze i indywidualne występy zawodników. Przechodź między tygodniami strzałkami u góry strony. Finanse są w zakładce Ekonomia, nastrój kibiców w osobnej zakładce.",
