  "Recherche par poste, âge, potentiel, prix (dont \"dans mon budget\") et jusqu'à 5 critères de caractéristiques, avec plusieurs tris (fin d'enchère, note, potentiel, prix, âge). Chaque annonce affiche la note du joueur, ses points forts et un bouton": "Wyszukiwanie według pozycji, wieku, potencjału, ceny (w tym „w moim budżecie”) i do 5 kryteriów cech, z kilkoma sortowaniami (koniec aukcji, ocena, potencjał, cena, wiek). Każde ogłoszenie pokazuje ocenę zawodnika, jego mocne strony i przycisk",
  "avec votre effectif ; on négocie d'abord le contrat avec le joueur, puis on enchérit. Pour vendre l'un de vos joueurs : menu ⋯ de l'Effectif ou bouton Vendre de sa fiche. L'identité de l'enchérisseur en tête reste privée.": "z twoim składem; najpierw negocjujesz kontrakt z zawodnikiem, potem licytujesz. Aby sprzedać zawodnika: menu ⋯ w Składzie lub przycisk Sprzedaj na jego karcie. Tożsamość prowadzącego licytanta pozostaje prywatna.",
