  "Prestige : {0} / 100 · {1}": "Prestiż: {0} / 100 · {1}",
  "La réputation du club auprès du public, bâtie sur les 5 dernières saisons : la division d'abord, puis le classement, les play-offs, la coupe et les montées. La saison la plus récente compte le plus. Mis à jour à chaque changement de saison.": "Reputacja klubu wśród publiczności, budowana na podstawie 5 ostatnich sezonów: najpierw dywizja, potem miejsce w tabeli, play-offy, puchar i awanse. Najbardziej liczy się ostatni sezon. Aktualizowana przy każdej zmianie sezonu.",
  "Aucune saison terminée : le prestige part de la moyenne de ta division.": "Żaden sezon jeszcze się nie zakończył: prestiż startuje od średniej twojej dywizji.",
