  "Deux types de programmes. Spécialisé : une seule compétence, à plein rendement. Polyvalent : deux compétences liées en même temps (par exemple Tir extérieur = Tir à mi-distance + Tir à 3 points), chacune progressant à 62 % du rythme d'un programme spécialisé. Au total, on progresse un peu plus (124 % contre 100 %), mais réparti sur deux compétences.": "Dwa rodzaje programów. Specjalistyczny: jedna umiejętność z pełną skutecznością. Wszechstronny: dwie powiązane umiejętności jednocześnie (np. Rzut z dystansu = Rzut z półdystansu + Rzut za 3 punkty), każda rozwija się w 62% tempa programu specjalistycznego. Łącznie postęp jest nieco większy (124% wobec 100%), ale rozłożony na dwie umiejętności.",
