  "Tous âges": "Każdy wiek",
  "Tous les postes": "Wszystkie pozycje",
  "Tous vos matchs de la saison, championnat et Coupe, groupés par mois. Les matchs se jouent tout seuls à l'heure prévue (championnat le mardi et le samedi à 20:00, Coupe le jeudi à 20:00) : connectez-vous pour les suivre en direct, ou laissez-les se dérouler sans vous.": "Wszystkie twoje mecze w sezonie, ligowe i pucharowe, pogrupowane według miesięcy. Mecze rozgrywają się same o wyznaczonej porze (liga we wtorek i sobotę o 20:00, Puchar w czwartek o 20:00): zaloguj się, żeby oglądać je na żywo, albo pozwól im toczyć się bez ciebie.",
  "tout": "wszystko",
  "Tout": "Wszystko",
  "Tout effacer": "Wyczyść wszystko",
  "Tout est à jour. Profitez-en pour regarder le marché.": "Wszystko jest aktualne. Wykorzystaj okazję, żeby zajrzeć na rynek.",
  "Tout potentiel": "Każdy potencjał",
  "Tout prix": "Każda cena",
  "Toute l'équipe devra apporter sa pierre à l'édifice, mais {player} aura un rôle important à jouer pour nous aider à progresser.": "Cała drużyna będzie musiała dołożyć swoją cegiełkę, ale {player} będzie miał ważną rolę do odegrania, żeby pomóc nam się rozwijać.",
  "Toute la ligue en 2 minutes": "Cała liga w 2 minuty",
