  "Transmettez ce code aux managers Premium que vous voulez inviter, de n'importe quel pays ou division. Ils le saisissent dans l'onglet Ligues privées.": "Przekaż ten kod menedżerom Premium, których chcesz zaprosić, z dowolnego kraju i ligi. Wpisują go w zakładce Ligi prywatne.",
