  "Courtside": "Courtside",
  "Salle : places converties (nouveaux plafonds Loges VIP / Courtside), différence remboursée": "Hala: miejsca przekształcone (nowe limity Loże VIP / Courtside), różnica zwrócona",
  "Trier les annonces": "Sortuj ogłoszenia",
