  "Votre équipe maîtrise plus ou moins chaque option tactique : une jauge par priorité offensive, par défense et par rythme (visible dans le menu \"Aspect travaillé\" de l'Entraînement). La maîtrise des options que vous jouez agit sur toute l'équipe en match, jusqu'à +/-6 %, en plus de l'alchimie.": "Twoja drużyna opanowała każdą opcję taktyczną w większym lub mniejszym stopniu: jeden wskaźnik na priorytet ofensywny, na obronę i na tempo (widoczny w menu „Ćwiczony element” w Treningu). Opanowanie opcji, które grasz, wpływa na całą drużynę w meczu, do +/-6%, oprócz chemii.",
