  "Aucune conversation pour l'instant. Pour écrire à un manager, ouvrez la page de son club puis « Envoyer un message ».": "Na razie brak rozmów. Aby napisać do menedżera, otwórz stronę jego klubu i kliknij „Wyślij wiadomość”.",
