  "(jeu intérieur, rebond, contre, défense intérieure) ou": "(gra pod koszem, zbiórki, bloki, obrona pod koszem) lub",
  "(défense extérieure, interceptions). Chaque semaine, tous les joueurs non blessés progressent un peu sur ces caractéristiques, qu'ils aient joué ou non, en plus de l'entraînement des fondamentaux. Moins sa spécialité compte de caractéristiques, plus chacune progresse vite. L'effet est surtout sensible chez les jeunes, il dépend aussi du poste et du gabarit de chaque joueur, et il est renforcé par l'entraîneur principal.": "(obrona na obwodzie, przechwyty). Co tydzień wszyscy zdrowi zawodnicy trochę poprawiają te cechy, niezależnie od tego, czy grali, oprócz treningu podstaw. Im mniej cech obejmuje specjalność, tym szybciej rośnie każda z nich. Efekt jest odczuwalny głównie u młodych, zależy też od pozycji i budowy ciała każdego zawodnika i jest wzmacniany przez głównego trenera.",
  "Entraîneur, entraîneur adjoint, analyste vidéo, recruteur, médecin, kiné : chacun a 5 niveaux, avec un coût et un effet croissants. L'analyste vidéo révèle par exemple certaines caractéristiques cachées des joueurs adverses avant un match, et le kiné réduit le risque de blessure.": "Trener, asystent trenera, analityk wideo, łowca talentów, lekarz, fizjoterapeuta: każdy ma 5 poziomów, z rosnącym kosztem i efektem. Analityk wideo odkrywa na przykład niektóre ukryte cechy zawodników rywala przed meczem, a fizjoterapeuta zmniejsza ryzyko kontuzji.",
  "staff médical": "sztab medyczny",
  "s'achète sur le même marché aux enchères, avec le même salaire qui grimpe chaque semaine. Le": "kupuje się na tym samym rynku aukcyjnym, z tą samą pensją rosnącą co tydzień.",
  "raccourcit la durée des nouvelles blessures. Le": "skraca czas nowych kontuzji.",
  "suit tout l'effectif : la forme physique remonte plus vite chaque jour et le risque de blessure en match baisse (il s'ajoute à l'effet de la salle de musculation). Plus leur niveau est élevé, plus l'effet est fort.": "opiekuje się całą kadrą: forma fizyczna odbudowuje się szybciej każdego dnia, a ryzyko kontuzji w meczu spada (dodatkowo do efektu siłowni). Im wyższy ich poziom, tym silniejszy efekt.",
