  "Ajoutez des places catégorie par catégorie (Tribune Supérieure, Tribune Centrale, Courtside, Loges VIP), au nombre que vous voulez : chaque place a un prix fixe, et chaque catégorie a un nombre maximum de places. Le nom de la salle évolue avec sa capacité.": "Dodawaj miejsca według kategorii (Trybuna Górna, Trybuna Centralna, Courtside, Loże VIP), w dowolnej liczbie: każde miejsce ma stałą cenę, a każda kategoria ma maksymalną liczbę miejsc. Nazwa hali zmienia się wraz z jej pojemnością.",
