  "Champion de sa ligue, {0} jouera en {1} la saison prochaine (prime de montée : {2} $). Profitez de l'intersaison pour renforcer l'effectif.": "Jako mistrz swojej ligi {0} zagra w przyszłym sezonie w: {1} (premia za awans: {2} $). Wykorzystaj przerwę międzysezonową, żeby wzmocnić kadrę.",
  "Champion de sa ligue, {0} jouera en {1} la saison prochaine. Profitez de l'intersaison pour renforcer l'effectif.": "Jako mistrz swojej ligi {0} zagra w przyszłym sezonie w: {1}. Wykorzystaj przerwę międzysezonową, żeby wzmocnić kadrę.",
