  "Montées et descentes": "Awanse i spadki",
  ", décidées le lundi d'intersaison et appliquées à la reprise : le champion des play-offs de chaque championnat monte ; en face, le 10e descend, puis le 9e, puis le perdant du barrage (7e contre 8e), autant qu'il y a de championnats ouverts juste en dessous. Une prime de montée est versée au club promu.": ", ustalane w poniedziałek przerwy międzysezonowej i stosowane po wznowieniu rozgrywek: mistrz play-offów każdej ligi awansuje; w zamian spada 10. drużyna, potem 9., a potem przegrany baraży (7. z 8.), tyle, ile jest otwartych lig tuż niżej. Awansujący klub otrzymuje premię za awans.",
  "(en bas du menu) : choisissez un pays (le vôtre par défaut) pour voir ses divisions ouvertes, son palmarès et les meilleurs joueurs de la saison. Pour afficher un autre championnat ou un club, tapez son nom dans la barre de recherche du haut (« II.2 », « Division III », un nom de club…) : classement, derniers résultats et effectif en lecture seule.": "(na dole menu): wybierz kraj (domyślnie twój), żeby zobaczyć jego otwarte dywizje, osiągnięcia i najlepszych zawodników sezonu. Aby wyświetlić inną ligę lub klub, wpisz jej nazwę w wyszukiwarce na górze („II.2”, „Dywizja III”, nazwa klubu…): tabela, ostatnie wyniki i kadra tylko do odczytu.",
