  "Coupe nationale": "Puchar Krajowy",
  "Dans les championnats par pays, c'est la": "W ligach krajowych jest to",
  ": tous les clubs du pays (512 au plus), avec des exempts au premier tour pour les divisions les plus hautes si le tableau n'est pas plein. Le club de la division inférieure part avec": ": wszystkie kluby kraju (maksymalnie 512), z wolnymi losami w pierwszej rundzie dla najwyższych dywizji, jeśli drabinka nie jest pełna. Klub z niższej dywizji zaczyna z",
  "+7 points par division d'écart": "+7 punktami za każdą dywizję różnicy",
  "(au plus +21), déjà au tableau d'affichage. Un adversaire d'un autre championnat se prépare comme les autres (Ordres, scouting) et sa fiche s'ouvre dans Planète Hoop. Chaque match de Coupe gagné rapporte une prime, de 50 000 $ aux premiers tours à 400 000 $ pour la finale. À l'intersaison, la": "(maksymalnie +21), już na tablicy wyników. Rywala z innej ligi przygotowuje się tak jak pozostałych (Polecenia, scouting), a jego strona otwiera się w Planecie Hoop. Każdy wygrany mecz pucharowy przynosi premię, od 50 000 $ w pierwszych rundach do 400 000 $ za finał. W przerwie międzysezonowej",
  "oppose le samedi à 20:00 le champion de Division I au vainqueur de la Coupe (ou au finaliste si c'est le même club), en direct et avec le même handicap : 200 000 $ pour le vainqueur.": "w sobotę o 20:00 zestawia mistrza Dywizji I ze zdobywcą Pucharu (lub finalistą, jeśli to ten sam klub), na żywo i z tym samym handicapem: 200 000 $ dla zwycięzcy.",
  "Coupe nationale · {0} · saison {1} : tous les clubs du pays, un tour chaque jeudi. Le club de division inférieure part avec": "Puchar Krajowy · {0} · sezon {1}: wszystkie kluby kraju, jedna runda w każdy czwartek. Klub z niższej dywizji zaczyna z",
  "(au plus +21), compris dans les scores.": "(maksymalnie +21), uwzględnionymi w wynikach.",
