  "Barrage (7e contre 8e) : {0} {1}-{2} {3}. Le club pourra être relégué si le championnat du dessous est ouvert.": "Baraż (7. z 8.): {0} {1}-{2} {3}. Klub może spaść, jeśli liga poniżej jest otwarta.",
