  "True shooting, réussite effective, stats par 36 minutes, +/- de la saison, et export du tableau en CSV (onglet Statistiques).": "True shooting, efektywna skuteczność, statystyki na 36 minut, +/- sezonu i eksport tabeli do CSV (zakładka Statystyki).",
