  "Une notification de votre navigateur (ou de l'application installée sur votre téléphone) quand votre match commence, qu'un joueur se blesse ou qu'une de vos enchères (joueur ou staff) se termine.": "Powiadomienie z przeglądarki (lub z aplikacji zainstalowanej na telefonie), gdy zaczyna się twój mecz, zawodnik doznaje kontuzji albo kończy się jedna z twoich licytacji (zawodnik lub sztab).",
  "▶ Revoir le direct": "▶ Obejrzyj transmisję ponownie",
