  "Les notifications ne sont pas encore disponibles sur ce serveur.": "Powiadomienia nie są jeszcze dostępne na tym serwerze.",
  "Ce navigateur ne gère pas les notifications. Sur iPhone, ajoute d'abord le jeu à l'écran d'accueil (Partager → Sur l'écran d'accueil).": "Ta przeglądarka nie obsługuje powiadomień. Na iPhonie najpierw dodaj grę do ekranu początkowego (Udostępnij → Do ekranu początkowego).",
  "Coup d'envoi de vos matchs, blessures, arrivées et départs, et vos enchères (joueurs et staff) : fin dans moins d'une heure, puis remportée ou perdue.": "Rozpoczęcie twoich meczów, kontuzje, przyjścia i odejścia oraz twoje licytacje (zawodnicy i sztab): mniej niż godzina do końca, potem wygrana lub przegrana.",
