  "Atteindre 100 victoires de championnat avec son club.": "Osiągnij 100 zwycięstw ligowych ze swoim klubem.",
  "Longue absence": "Długa nieobecność",
  ": sans aucune visite pendant 45 jours, votre club est confié à l'IA (effectif, nom et palmarès conservés). Reconnectez-vous à votre compte pour le récupérer, s'il n'a pas été repris entre-temps par un autre manager ; sinon un nouveau club vous est attribué.": ": po 45 dniach bez żadnej wizyty twój klub zostaje przekazany AI (kadra, nazwa i osiągnięcia zostają zachowane). Zaloguj się ponownie na swoje konto, aby go odzyskać, o ile w międzyczasie nie przejął go inny menedżer; w przeciwnym razie otrzymasz nowy klub.",
  "Bon retour à {0} !": "Witaj z powrotem w {0}!",
  "Pendant votre absence, le club a été géré par l'IA. Vérifiez votre effectif, vos ordres et votre budget.": "Podczas twojej nieobecności klubem zarządzała AI. Sprawdź swoją kadrę, polecenia i budżet.",
  "Contre un club d'un autre championnat": "Z klubem z innej ligi",
  ", même d'un autre pays : tapez son nom dans la recherche d'adversaire, les clubs du monde entier apparaissent sous ceux de votre ligue (drapeau et division). Mêmes règles : jour de repos des deux clubs, heure de Paris, invitation à accepter contre un manager (il est prévenu dans son fil d'actualité).": ", nawet z innego kraju: wpisz jego nazwę w wyszukiwarce rywali, kluby z całego świata pojawiają się pod klubami twojej ligi (flaga i dywizja). Te same zasady: dzień odpoczynku obu klubów, czas paryski, zaproszenie do zaakceptowania w przypadku menedżera (otrzymuje powiadomienie w aktualnościach).",
  "Club d'un autre championnat ({0}) : l'amical se joue à la même heure (Paris) pour les deux clubs.": "Klub z innej ligi ({0}): mecz towarzyski odbywa się o tej samej godzinie (czasu paryskiego) dla obu klubów.",
  "Autre championnat": "Inna liga",
  "Un des deux clubs a changé de championnat.": "Jeden z dwóch klubów zmienił ligę.",
  "Adversaire du même championnat : passez par la liste habituelle.": "Rywal z tej samej ligi: skorzystaj ze zwykłej listy.",
  "Monde entier": "Cały świat",
  "Mon pays": "Mój kraj",
  "Mon championnat": "Moja liga",
  "Marché mondial": "Rynek światowy",
  ": les annonces de tous les championnats, dans tous les pays, apparaissent aussi (drapeau et division du vendeur sur la carte ; filtre « Monde entier », « Mon championnat » ou le pays de votre choix, avec une recherche). On y enchérit de la même façon ; le joueur rejoint votre club à la clôture de l'enchère. Les annonces des autres championnats se mettent à jour toutes les quelques minutes : si quelqu'un a surenchéri entre-temps, votre enchère est refusée et le prix actualisé.": ": pojawiają się też ogłoszenia ze wszystkich lig we wszystkich krajach (flaga i dywizja sprzedającego na karcie; filtr „Cały świat”, „Moja liga” lub dowolny wybrany kraj, z wyszukiwarką). Licytuje się tak samo; zawodnik dołącza do twojego klubu po zamknięciu licytacji. Ogłoszenia z innych lig odświeżają się co kilka minut: jeśli ktoś w międzyczasie przebił ofertę, twoja oferta zostaje odrzucona, a cena zaktualizowana.",
