  "À la fin de la saison régulière, la ligue décerne ses": "Na koniec sezonu zasadniczego liga przyznaje swoje",
  "récompenses": "nagrody",
  ": MVP, 5 majeur (un joueur par poste), meilleur jeune (21 ans ou moins), 6e homme (un joueur surtout remplaçant) et meilleur défenseur, puis le": ": MVP, pierwsza piątka (jeden zawodnik na pozycję), najlepszy młody zawodnik (21 lat lub mniej), szósty zawodnik (grający głównie z ławki) i najlepszy obrońca, a następnie",
  "(dans l'équipe championne) après la finale. Elles se calculent sur la saison régulière, pour les joueurs qui ont disputé au moins 40 % des journées, et s'affichent dans l'onglet Ligue.": "(z drużyny mistrzowskiej) po finale. Są obliczane na podstawie sezonu zasadniczego dla zawodników, którzy zagrali w co najmniej 40% kolejek, i wyświetlane w zakładce Liga.",
  "À mi-saison, le dimanche à 20h, les 10 meilleurs joueurs du pays affrontent les 10 meilleurs étrangers lors du": "W połowie sezonu, w niedzielę o 20:00, 10 najlepszych zawodników kraju mierzy się z 10 najlepszymi obcokrajowcami w",
  ", un match d'exhibition sans effet sur le classement ni sur la forme. La fiche de chaque joueur montre sa nationalité et sa": ", meczu pokazowym bez wpływu na tabelę i formę. Profil każdego zawodnika pokazuje jego narodowość i",
  "carrière": "karierę",
  "saison par saison, avec ses distinctions.": "sezon po sezonie, wraz z wyróżnieniami.",
  "On y trouve aussi vos": "Znajdziesz tam też swoje",
  "succès": "osiągnięcia",
  "de manager (première victoire, séries, titres, salle pleine, jeune formé au club devenu titulaire...), avec une barre de progression pour ceux qui restent à débloquer. Les autres managers les voient, avec votre bilan et vos titres, dans le profil affiché sur la fiche de votre club.": "menedżerskie (pierwsze zwycięstwo, serie, tytuły, pełna hala, wychowanek, który wywalczył miejsce w pierwszej piątce...), z paskiem postępu dla tych, które pozostają do odblokowania. Inni menedżerowie widzą je, razem z twoim bilansem i tytułami, w profilu wyświetlanym na stronie twojego klubu.",
