  "Recruter au marché du staff": "Zatrudnianie na rynku sztabu",
  "Le staff se recrute aux enchères, dans l'onglet Marché, rubrique Staff. Chaque candidat (niveau 1 à 5) reste en vente 1 jour réel et les autres clubs peuvent surenchérir jusqu'au bout. Votre mise n'est pas un paiement unique : c'est le salaire hebdomadaire de départ du membre du staff, qui augmente ensuite un peu chaque semaine.": "Sztab zatrudnia się na aukcji, w zakładce Rynek, sekcja Sztab. Każdy kandydat (poziom 1–5) jest wystawiony przez 1 rzeczywisty dzień, a inne kluby mogą przebijać do końca. Twoja oferta to nie jednorazowa płatność: to początkowa tygodniowa pensja członka sztabu, która potem co tydzień trochę rośnie.",
  "Gagner une enchère remplace votre membre du staff actuel au même poste, sans indemnité. Le montant de vos enchères en tête est réservé sur votre budget jusqu'à la fin de la vente.": "Wygrana aukcja zastępuje obecnego członka sztabu na tym samym stanowisku, bez odprawy. Kwota Twoich prowadzących ofert jest zarezerwowana w budżecie do końca aukcji.",
