  "des deux clubs (aucun match officiel ce jour-là), à l'heure de votre choix, jusqu'à 3 semaines à l'avance, et un seul par jour. Une équipe CPU accepte tout de suite ; un autre manager reçoit un message privé et doit accepter avant l'heure du match.": "obu klubów (tego dnia bez meczu oficjalnego), o wybranej przez ciebie godzinie, do 3 tygodni wcześniej i tylko jeden dziennie. Drużyna CPU akceptuje od razu; inny menedżer dostaje prywatną wiadomość i musi zaakceptować przed godziną meczu.",
  "de l'amical, vous pouvez aligner les jeunes de l'académie ; sans composition propre, l'amical se joue avec les ordres actuels du club.": "meczu towarzyskiego możesz wystawić juniorów z akademii; bez własnego składu mecz towarzyski rozgrywany jest z bieżącymi poleceniami klubu.",
