  "… Un nouveau manager arrive dans la division la plus haute où il reste un club de l'IA ; quand tout est plein (plus de 10 managers dans un championnat), le championnat suivant s'ouvre tout seul. Les matchs se jouent à 20:00 heure locale, et tous les pays suivent les mêmes semaines.": "… Nowy menedżer trafia do najwyższej dywizji, w której pozostał jeszcze klub prowadzony przez AI; gdy wszystko jest pełne (ponad 10 menedżerów w lidze), następna liga otwiera się sama. Mecze rozgrywane są o 20:00 czasu lokalnego, a wszystkie kraje mają te same tygodnie.",
