  "Dernière saison de contrat : il ne peut plus être vendu pendant la seconde moitié de la saison. Sans prolongation, il partira libre en fin de saison.": "Ostatni sezon kontraktu: w drugiej połowie sezonu nie można go już sprzedać. Bez przedłużenia odejdzie za darmo po sezonie.",
