  "{0} accepte : prolongé jusqu'à la saison {1}, {2} / sem. à partir de la saison {3}.": "{0} się zgadza: przedłużony do sezonu {1}, {2} / tydz. od sezonu {3}.",
  "{0} refuse votre offre et perd en motivation. Sa demande augmente ; vous pourrez lui faire une nouvelle offre la semaine prochaine.": "{0} odrzuca twoją ofertę i traci motywację. Jego żądania rosną; nową ofertę możesz złożyć w przyszłym tygodniu.",
  "Il a refusé {0} offres : il ne signera plus qu'au salaire qu'il demande.": "Odrzucił {0} ofert: podpisze już tylko za żądaną pensję.",
