  "Ce joueur est en dernière saison de contrat : il ne peut plus être vendu pendant la seconde moitié de la saison (il partira libre s'il n'est pas prolongé).": "Ten zawodnik jest w ostatnim sezonie kontraktu: w drugiej połowie sezonu nie można go już sprzedać (bez przedłużenia odejdzie za darmo).",
