  "Aucun duo possible : il faut un jeune (≤ 22 ans) et un vétéran (≥ 29 ans) au même poste.": "Brak możliwej pary: potrzebny młody (≤ 22 lata) i weteran (≥ 29 lat) na tej samej pozycji.",
