  "Ces ordres valent pour tous vos matchs de ligue privée à venir, jamais pour les matchs officiels. Sans ordres enregistrés, la ligue privée se joue avec les ordres actuels du club.": "Te polecenia obowiązują we wszystkich nadchodzących meczach ligi prywatnej, nigdy w meczach oficjalnych. Bez zapisanych poleceń liga prywatna jest rozgrywana z aktualnymi poleceniami klubu.",
  "La ligue privée se jouera avec les ordres du club.": "Liga prywatna zostanie rozegrana z poleceniami klubu.",
