  "Plus vos supporters sont heureux, plus ils achètent. Les maillots les plus vendus sont ceux de vos meilleurs joueurs.": "Im bardziej zadowoleni kibice, tym więcej kupują. Najlepiej sprzedają się koszulki twoich najlepszych zawodników.",
