  "Tactique × {0}": "Taktyka × {0}",
  "Récupération × {0}": "Regeneracja × {0}",
  "Physique × {0}": "Motoryka × {0}",
  "Blessé à l'entraînement": "Kontuzja na treningu",
  "{0} n'a joué que {1} min cette semaine sur {2} : son plan ne compte qu'à {3} %.": "{0} zagrał w tym tygodniu tylko {1} z {2} min: jego plan liczy się tylko w {3}%.",
  "Forme moyenne de l'équipe": "Średnia forma drużyny",
  "Plans individuels.": "Plany indywidualne.",
  "Chaque place de plan associe un joueur à un programme parmi les 13 fondamentaux (tir, passe, défense, etc.), quel que soit son poste. Le nombre de places dépend de l'entraîneur : 3 aux niveaux 1 et 2, 4 aux niveaux 3 et 4, 5 au niveau 5. Sans entraîneur, aucun fondamental n'est travaillé. L'entraînement se déclenche le lundi à 6h, heure de Paris.": "Każde miejsce w planie łączy zawodnika z programem spośród 13 podstaw (rzut, podanie, obrona itd.), niezależnie od jego pozycji. Liczba miejsc zależy od trenera: 3 na poziomach 1 i 2, 4 na poziomach 3 i 4, 5 na poziomie 5. Bez trenera żadna podstawa nie jest trenowana. Trening odbywa się w poniedziałek o 6:00 czasu paryskiego.",
  "Rendement.": "Wydajność.",
  "Un joueur en plan doit avoir joué 30 minutes dans la semaine (championnat, Coupe, play-offs et amicaux) pour un plein rendement, moins s'il a peu joué. L'âge (les jeunes apprennent plus vite), le gabarit, le niveau de l'entraîneur et l'intensité de la semaine font varier le rendement, affiché en % pour chaque joueur. Le poste n'a plus d'effet.": "Zawodnik w planie musi rozegrać w tygodniu 30 minut (liga, Puchar, play-off i sparingi), by mieć pełną wydajność, mniej, jeśli grał mało. Wiek (młodzi uczą się szybciej), budowa ciała, poziom trenera i intensywność tygodnia zmieniają wydajność, pokazaną w % dla każdego zawodnika. Pozycja nie ma już znaczenia.",
  "Intensité.": "Intensywność.",
  "Légère : progression plus lente, meilleure récupération. Normale. Intense : progression plus rapide, mais forme en baisse et petit risque de blessure pour les joueurs en plan.": "Lekka: wolniejsze postępy, lepsza regeneracja. Normalna. Intensywna: szybsze postępy, ale spadek formy i niewielkie ryzyko kontuzji dla zawodników w planie.",
  "Plafond.": "Pułap.",
  "Chaque joueur a une marge de progression propre ; quand elle se réduit, la progression ralentit peu à peu, sans s'arrêter net. Un bon entraîneur repousse ce plafond. Quand un joueur ne progresse plus, le bilan du lundi propose un autre programme (bouton Appliquer).": "Każdy zawodnik ma własny zapas rozwoju; gdy maleje, postępy stopniowo zwalniają, nie zatrzymując się nagle. Dobry trener podnosi ten pułap. Gdy zawodnik przestaje robić postępy, podsumowanie poniedziałku proponuje inny program (przycisk Zastosuj).",
  "Spécialités de l'entraîneur.": "Specjalności trenera.",
  "Attaque ou Défense : programmes de cette famille plus efficaces. Physique : jours Physique plus efficaces. Jeunes : joueurs de 21 ans et moins, et académie, plus efficaces.": "Atak lub Obrona: programy z tej grupy są skuteczniejsze. Motoryka: dni motoryczne są skuteczniejsze. Młodzież: zawodnicy do 21 lat i akademia trenują skuteczniej.",
  "Collectif.": "Trening zespołowy.",
  "Chaque jour sans match officiel, choisissez Tactique (un aspect précis : une priorité offensive, une défense ou un rythme ; plus il est neuf, plus il progresse vite), Récupération (forme en hausse pour tout l'effectif) ou Physique (petit gain physique, surtout pour les jeunes). Un jour d'amical, la tactique n'est pas possible, mais les joueurs non retenus pour l'amical peuvent récupérer ou faire du physique.": "W każdy dzień bez oficjalnego meczu wybierz Taktykę (jeden konkretny element: priorytet ofensywny, obronę lub tempo; im nowszy, tym szybciej rośnie), Regenerację (wzrost formy całej kadry) lub Motorykę (mały zysk fizyczny, głównie dla młodych). W dniu sparingu taktyka jest niemożliwa, ale zawodnicy niepowołani na sparing mogą się regenerować lub trenować motorykę.",
  "Mental et parrainage.": "Mentalność i mentoring.",
  "Le mental progresse en partie tout seul, en partie avec les minutes jouées dans la semaine. Un jeune (22 ans au plus) associé à un vétéran (29 ans au moins) du même poste progresse plus vite au mental (2 parrainages au plus).": "Mentalność rozwija się częściowo sama, częściowo dzięki minutom rozegranym w tygodniu. Młody (najwyżej 22 lata) połączony z weteranem (co najmniej 29 lat) z tej samej pozycji szybciej rozwija mentalność (najwyżej 2 pary).",
  "Chaque semaine (le lundi à 6h), vos joueurs en plan individuel travaillent le programme choisi pour eux parmi les 13 fondamentaux. Le nombre de places dépend de votre entraîneur (3 à 5) : sans entraîneur, pas de travail des fondamentaux. Le Physique et le Mental évoluent tout seuls, le Mental aussi avec les minutes jouées.": "Co tydzień (w poniedziałek o 6:00) zawodnicy z planem indywidualnym trenują wybrany dla nich program spośród 13 podstaw. Liczba miejsc zależy od trenera (od 3 do 5): bez trenera nie ma treningu podstaw. Motoryka i Mentalność rozwijają się same, Mentalność także dzięki rozegranym minutom.",
  "Un joueur en plan doit jouer 30 minutes dans la semaine (championnat, Coupe, play-offs et amicaux) pour un plein rendement ; le poste n'a plus d'importance.": "Zawodnik w planie musi zagrać w tygodniu 30 minut (liga, Puchar, play-off i sparingi), by mieć pełną wydajność; pozycja nie ma już znaczenia.",
  "Chaque jour sans match, choisissez Tactique (un aspect précis), Récupération (forme +15) ou Physique (petit gain physique, surtout pour les jeunes). Un jour d'amical, les joueurs non retenus peuvent récupérer ou faire du physique.": "W każdy dzień bez meczu wybierz Taktykę (jeden konkretny element), Regenerację (forma +15) lub Motorykę (mały zysk fizyczny, głównie dla młodych). W dniu sparingu niepowołani zawodnicy mogą się regenerować lub trenować motorykę.",
  "Une tactique neuve s'apprend vite (+12 par jour à 40), une tactique déjà maîtrisée beaucoup moins (+4 par jour à 95). Le détail est dans le Guide.": "Nowej taktyki uczy się szybko (+12 dziennie przy 40), już opanowanej znacznie wolniej (+4 dziennie przy 95). Szczegóły w Przewodniku.",
  // Entraînement v2 (retour utilisateur 2026-10-01).
  "+{0}/jour": "+{0}/dzień",
  "Votre équipe maîtrise plus ou moins chaque option tactique : une jauge par priorité offensive, par défense et par rythme (visible dans le menu \"Aspect travaillé\" de l'Entraînement). La maîtrise des options que vous jouez agit sur toute l'équipe en match, jusqu'à +/-8 %, en plus de l'alchimie.": "Twoja drużyna opanowała każdą opcję taktyczną w większym lub mniejszym stopniu: jeden wskaźnik na priorytet ofensywny, na obronę i na tempo (widoczny w menu „Ćwiczony element” w Treningu). Opanowanie opcji, które grasz, wpływa na całą drużynę w meczu, do +/-8%, oprócz chemii.",
  "sur cette option la fait monter à chaque jour de repos écoulé, selon son niveau : +12 par jour à 40, +9 à 60, +6 à 80, +4 à 95 (jamais un jour d'amical). Un": "na tej opcji podnosi ją w każdy miniony dzień odpoczynku, zależnie od poziomu: +12 dziennie przy 40, +9 przy 60, +6 przy 80, +4 przy 95 (nigdy w dniu sparingu).",
